from __future__ import annotations
import math

def sorting_information(n: int, temperature: float = 1.0) -> dict[str, float | int]:
    if n < 0 or temperature < 0:
        raise ValueError("inputs must be nonnegative")
    ln_fact = math.lgamma(n + 1)
    bits = ln_fact / math.log(2)
    return {"permutations": math.factorial(n), "erased_bits": bits,
            "minimum_comparisons": math.ceil(bits - 1e-12),
            "history_states": math.factorial(n),
            "landauer_scale": temperature * ln_fact}

for n in range(2, 11):
    print(n, sorting_information(n))

from __future__ import annotations

def search_contrast(n: int) -> tuple[int, int]:
    if n < 0:
        raise ValueError("n must be nonnegative")
    return n, (1 << (n + 1)) - 1

for n in (8, 16, 24, 32):
    description, candidates = search_contrast(n)
    print(f"n={n}: description scale={description}, candidates={candidates:,}")

